const htmlCache=new WeakMap();function writeHTML(node,value){if(htmlCache.get(node)===value)return false;htmlCache.set(node,value);node.innerHTML=value;return true;}

const T=TerminalRail,$=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';let station=new T.Station(5),minutes=5,mode='expert',selected=null,chosenPlatform=null,paused=true,speed=1,last=performance.now(),lastPaint=0,resultShown=false,cardKey='',pendingOrigin=null,lastCandidate=null;
