function actual(t,due){return t===null?'未':`<span class="${t>due+.05?'late':'good'}">${time(t)}${t>due+.05?' +'+Math.round(t-due)+'秒':''}</span>`;}
function report(){paused=true;const r=station.result();$('terminal-modal').style.display='grid';$('terminal-modal').innerHTML=`<section class="modalbox"><div class="eyebrow">SHIOMI CENTRAL / SHIFT REPORT</div><h2>汐見中央駅・勤務成績</h2><div class="terminal-grade">${r.grade}<strong>${r.score}点</strong></div><div class="resultsgrid"><div class="resultmetric"><b>${r.correct}/${r.total}</b><small>所定番線</small></div><div class="resultmetric"><b>${r.ontime}/${r.total}</b><small>15秒以内の発着</small></div><div class="resultmetric"><b>${r.completed}/${r.total}</b><small>発着完了</small></div><div class="resultmetric"><b>${Math.round(r.delay)}秒</b><small>延べ遅延</small></div></div><p>${T.MODES[station.difficulty].label}・${station.minutes}分 ／ ダイヤ通り ${r.compliant}/${r.rows.length}列車。最大遅延 ${Math.round(r.max)}秒。</p><div class="tablewrap resulttable"><table><thead><tr><th>列車</th><th>番線 所定→実績</th><th>到着</th><th>出発</th></tr></thead><tbody>${r.rows.map(t=>`<tr><td>${t.id} ${t.kind}</td><td>${t.p}/${t.scheduledDepP||t.p} → ${t.arrP??'—'} / ${t.depP??'—'}</td><td>${actual(t.arr,station.plan.find(p=>p.id===t.id).arr)}</td><td>${actual(t.dep,station.plan.find(p=>p.id===t.id).dep)}</td></tr>`).join('')}</tbody></table></div><div class="resultactions"><button id="terminal-report-csv">CSV保存</button><button id="terminal-review">盤面を確認</button><button id="terminal-retry" class="primary">次の勤務</button><a class="station-select" href="index.html">駅選択</a></div></section>`;$('terminal-report-csv').onclick=exportCSV;$('terminal-review').onclick=()=>{$('terminal-modal').style.display='none';};$('terminal-retry').onclick=setup;}
function exportCSV(){const lines=[['駅','列車','種別','出発地','行先','所定番線','到着番線','出発番線','所定着','所定発','実到着','実出発','到着遅延秒','出発遅延秒'].join(',')];for(const p of station.plan){const r=station.records[p.id];lines.push(['汐見中央',p.id,p.kind,T.ENDS[p.from].name,T.ENDS[p.to].name,p.p,r.arrP??'',r.depP??'',time(p.arr),time(p.dep),r.arr===null?'':time(r.arr),r.dep===null?'':time(r.dep),r.arr===null?'':Math.max(0,Math.round(r.arr-p.arr)),r.dep===null?'':Math.max(0,Math.round(r.dep-p.dep))].join(','));}const u=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='汐見中央駅_'+station.minutes+'分_'+station.difficulty+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const audio={renderer:new RailSound.Renderer(window.AudioContext||window.webkitAudioContext),muted:false,volume:.4,approaches:Object.fromEntries(T.publicGates.map(g=>[g,{id:null,ack:false,next:0}])),unlock(){try{this.renderer.ready();this.renderer.volume(this.muted?0:this.volume);}catch{}},reset(){for(const[g,a]of Object.entries(this.approaches)){this.renderer.cancel(g);a.id=null;a.ack=false;a.next=0;}},update(dt=0){for(const[g,a]of Object.entries(this.approaches)){const t=station.trainAt(g+'I')||station.trainAt(g+'AI');if(a.id!==(t?.id||null)){this.renderer.cancel(g);a.id=t?.id||null;a.ack=false;a.next=0;}const active=a.id&&!a.ack&&!this.muted&&this.volume>0&&!paused&&station.running&&!station.finished&&!document.hidden;if(!active){this.renderer.cancel(g);a.next=0;}else if(T.ENDS[g].physical==='W'){if(a.next!==Infinity&&this.renderer.sustain(g,{AW:520,BW:480,CW:440}[g])!==false)a.next=Infinity;}else{a.next-=dt;if(a.next<=0){this.renderer.buzzer(g,{AE:390,BE:350,CE:310}[g],.3);a.next=.5;}}$('sound-status-'+g).textContent=active?'動作中':'停止中';$('sound-stop-'+g).disabled=!a.id||a.ack;}}};
